/* OpenLearnHub - Global Styles */

:root {
  --primary: #0a0a23;
  --accent: #feac32;
  --link-blue: #002ead;
  --bg: #ffffff;
  --bg-light: #f5f6f7;
  --text: #1b1b32;
  --text-secondary: #5a5a6e;
  --border: #d0d0d5;
  --tag-ai: #1b1b32;
  --tag-webscraping: #2a2a40;
  --tag-databases: #3b3b4f;
  --tag-elasticsearch: #0a0a23;
  --tag-dataeng: #1b1b32;
  --tag-python: #2a2a40;
  --tag-nodejs: #3b3b4f;
  --tag-googlesheets: #0a0a23;
  --tag-general: #1b1b32;
  --tag-javascript: #2a2a40;
  --tag-webdev: #3b3b4f;
  --tag-react: #0a0a23;
  --tag-tech: #1b1b32;
  --tag-youtube: #2a2a40;
  --tag-startup: #3b3b4f;
  --tag-software: #0a0a23;
  --tag-design: #1b1b32;
  --tag-productivity: #2a2a40;
  --tag-life: #3b3b4f;
  --tag-css: #0a0a23;
  --tag-self: #1b1b32;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

/* Header */
.site-header {
  background: var(--primary);
  color: #fff;
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  gap: 1rem;
}

.logo {
  font-weight: 800;
  font-size: 1.25rem;
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  white-space: nowrap;
}

.logo-mark {
  width: 28px;
  height: 28px;
  background: var(--accent);
  color: var(--primary);
  border-radius: 4px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-weight: 900;
  font-size: 0.875rem;
}

.search-bar {
  flex: 1;
  max-width: 480px;
  position: relative;
}

.search-bar input {
  width: 100%;
  padding: 0.5rem 1rem 0.5rem 2.25rem;
  border-radius: 4px;
  border: 1px solid #3b3b4f;
  background: #2a2a40;
  color: #fff;
  font-size: 0.875rem;
  outline: none;
  transition: border-color 0.2s;
}

.search-bar input::placeholder {
  color: #858591;
}

.search-bar input:focus {
  border-color: var(--accent);
}

.search-icon {
  position: absolute;
  left: 0.75rem;
  top: 50%;
  transform: translateY(-50%);
  color: #858591;
  font-size: 0.875rem;
}

.desktop-nav {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.desktop-nav a {
  font-size: 0.9375rem;
  font-weight: 500;
  opacity: 0.9;
  transition: opacity 0.2s;
}

.desktop-nav a:hover {
  opacity: 1;
  color: var(--accent);
}

.menu-toggle {
  display: none;
  background: none;
  border: none;
  color: #fff;
  font-size: 1.5rem;
  cursor: pointer;
  padding: 0.25rem;
}

.mobile-nav {
  display: none;
  background: #1b1b32;
  border-top: 1px solid #3b3b4f;
}

.mobile-nav.open {
  display: block;
}

.mobile-nav a {
  display: block;
  padding: 1rem 1.5rem;
  font-size: 1rem;
  font-weight: 500;
  border-bottom: 1px solid #3b3b4f;
}

.mobile-nav a:hover {
  background: #2a2a40;
  color: var(--accent);
}

/* Banner */
.hero-banner {
  background: var(--primary);
  color: #fff;
  text-align: center;
  padding: 0.75rem 1rem;
  font-size: 0.9375rem;
  font-weight: 500;
}

.hero-banner a {
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 2px;
}

/* Container */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Section titles */
.section-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 1.25rem;
  color: var(--text);
}

/* Article Cards */
.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.article-card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
  transition: box-shadow 0.2s, transform 0.2s;
  cursor: pointer;
}

.article-card:hover {
  box-shadow: 0 4px 16px rgba(0,0,0,0.08);
  transform: translateY(-2px);
}

.article-card .thumb {
  position: relative;
  width: 100%;
  aspect-ratio: 16/9;
  overflow: hidden;
}

.article-card .thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s;
}

.article-card:hover .thumb img {
  transform: scale(1.03);
}

.article-card .tag-label {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  background: var(--primary);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
}

.article-card .card-body {
  padding: 1rem;
}

.article-card .card-title {
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 0.75rem;
  color: var(--text);
}

.article-card .card-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.article-card .card-meta img {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  object-fit: cover;
}

.article-card .card-meta .author-name {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.article-card .card-meta .time {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  margin-left: auto;
}

/* Featured article */
.featured-card {
  grid-column: span 2;
  display: flex;
  flex-direction: column;
}

.featured-card .thumb {
  aspect-ratio: 16/9;
}

.featured-card .card-title {
  font-size: 1.35rem;
}

/* Load more */
.load-more-wrap {
  text-align: center;
  margin-top: 2rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1.5rem;
  border-radius: 4px;
  font-size: 0.9375rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: background 0.2s, transform 0.1s;
}

.btn-primary {
  background: var(--accent);
  color: var(--primary);
}

.btn-primary:hover {
  background: #e69b2a;
}

.btn:active {
  transform: scale(0.98);
}

.btn-outline {
  background: transparent;
  color: var(--text);
  border: 2px solid var(--border);
}

.btn-outline:hover {
  border-color: var(--text);
}

/* Tag page header */
.tag-header {
  padding: 2rem 0;
  border-bottom: 1px solid var(--border);
  margin-bottom: 1.5rem;
}

.tag-header h1 {
  font-size: 2rem;
  font-weight: 800;
  margin-bottom: 0.25rem;
}

.tag-header p {
  color: var(--text-secondary);
  font-size: 0.9375rem;
}

/* Popular tags */
.popular-tags {
  display: flex;
  gap: 0.75rem;
  overflow-x: auto;
  padding-bottom: 0.5rem;
  margin-bottom: 1.5rem;
}

.popular-tags::-webkit-scrollbar {
  height: 4px;
}

.popular-tags::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 2px;
}

.tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.4rem 0.75rem;
  border-radius: 20px;
  background: var(--bg-light);
  border: 1px solid var(--border);
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text);
  white-space: nowrap;
  transition: background 0.2s;
}

.tag-chip:hover {
  background: var(--border);
}

.tag-chip .count {
  color: var(--text-secondary);
  font-weight: 500;
}

/* Footer */
.site-footer {
  background: var(--bg-light);
  border-top: 1px solid var(--border);
  padding: 2.5rem 0;
  margin-top: 3rem;
}

.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.footer-mission {
  font-size: 0.875rem;
  color: var(--text-secondary);
  max-width: 720px;
  margin-bottom: 1.5rem;
  line-height: 1.6;
}

.footer-trending {
  margin-bottom: 1.5rem;
}

.footer-trending strong {
  font-size: 0.875rem;
  color: var(--text);
  margin-right: 0.5rem;
}

.footer-trending a {
  font-size: 0.875rem;
  color: var(--link-blue);
  margin-right: 0.75rem;
}

.footer-trending a:hover {
  text-decoration: underline;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.footer-links a {
  font-size: 0.8125rem;
  color: var(--text-secondary);
}

.footer-links a:hover {
  color: var(--text);
}

/* Donation page */
.donate-hero {
  background: var(--primary);
  color: #fff;
  padding: 3rem 0;
}

.donate-hero h1 {
  font-size: 2.25rem;
  font-weight: 800;
  margin-bottom: 1rem;
}

.donate-hero p {
  font-size: 1.0625rem;
  max-width: 640px;
  line-height: 1.6;
  opacity: 0.92;
}

.donation-form-section {
  padding: 2rem 0;
}

.donation-card {
  max-width: 560px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1.5rem;
}

.amount-tabs {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.amount-tab {
  flex: 1;
  padding: 0.75rem;
  border: 2px solid var(--border);
  border-radius: 6px;
  background: var(--bg);
  font-size: 1rem;
  font-weight: 700;
  color: var(--text);
  cursor: pointer;
  transition: border-color 0.2s, background 0.2s;
}

.amount-tab:hover {
  border-color: var(--accent);
}

.amount-tab.active {
  border-color: var(--accent);
  background: rgba(254, 172, 50, 0.08);
}

.donation-desc {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  margin-bottom: 1rem;
  line-height: 1.5;
}

.donation-sub {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  margin-top: 0.75rem;
}

.donation-sub a {
  color: var(--link-blue);
  text-decoration: underline;
}

/* Supporter benefits */
.benefits-section {
  padding: 2rem 0;
  background: var(--bg-light);
}

.benefits-section h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.benefits-list {
  list-style: none;
}

.benefits-list li {
  padding: 0.5rem 0;
  font-size: 0.9375rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.benefits-list li::before {
  content: "✓";
  color: var(--accent);
  font-weight: 700;
}

/* Initiatives & Achievements */
.initiatives-section,
.achievements-section {
  padding: 2rem 0;
}

.initiatives-section h2,
.achievements-section h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.initiatives-list,
.achievements-list {
  list-style: disc;
  padding-left: 1.25rem;
}

.initiatives-list li,
.achievements-list li {
  padding: 0.35rem 0;
  font-size: 0.9375rem;
  color: var(--text);
}

/* FAQ Accordion */
.faq-section {
  padding: 2rem 0;
  background: var(--bg-light);
}

.faq-section h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.accordion-item {
  border-bottom: 1px solid var(--border);
}

.accordion-header {
  width: 100%;
  text-align: left;
  padding: 1rem 0;
  background: none;
  border: none;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.accordion-header:hover {
  color: var(--link-blue);
}

.accordion-icon {
  font-size: 1.25rem;
  transition: transform 0.2s;
  color: var(--text-secondary);
}

.accordion-item.open .accordion-icon {
  transform: rotate(45deg);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.accordion-item.open .accordion-body {
  max-height: 200px;
  padding-bottom: 1rem;
}

.accordion-body p {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* Learn page */
.welcome-section {
  padding: 2rem 0;
  border-bottom: 1px solid var(--border);
}

.welcome-section h1 {
  font-size: 1.75rem;
  font-weight: 800;
  margin-bottom: 0.5rem;
}

.welcome-section p {
  color: var(--text-secondary);
  font-size: 1rem;
}

.curriculum-section {
  padding: 2rem 0;
}

.curriculum-section h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.cert-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1rem;
}

.cert-card {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  transition: box-shadow 0.2s;
}

.cert-card:hover {
  box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}

.cert-icon {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  background: var(--primary);
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}

.cert-name {
  font-size: 0.9375rem;
  font-weight: 600;
  line-height: 1.35;
}

.challenge-section {
  padding: 2rem 0;
  background: var(--bg-light);
}

.challenge-section h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.challenge-section p {
  color: var(--text-secondary);
  margin-bottom: 0.75rem;
}

.challenge-links a {
  color: var(--link-blue);
  font-size: 0.9375rem;
  margin-right: 1.25rem;
}

.challenge-links a:hover {
  text-decoration: underline;
}

.lang-section,
.interview-section,
.prof-section {
  padding: 2rem 0;
  border-bottom: 1px solid var(--border);
}

.lang-section h2,
.interview-section h2,
.prof-section h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
}

.lang-section h3,
.interview-section h3,
.prof-section h3 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  color: var(--text-secondary);
}

.lang-section a,
.interview-section a,
.prof-section a {
  color: var(--link-blue);
  font-size: 0.9375rem;
  margin-right: 1rem;
}

.lang-section a:hover,
.interview-section a:hover,
.prof-section a:hover {
  text-decoration: underline;
}

/* Responsive */
@media (max-width: 992px) {
  .article-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .featured-card {
    grid-column: span 2;
  }
}

@media (max-width: 640px) {
  .article-grid {
    grid-template-columns: 1fr;
  }
  .featured-card {
    grid-column: span 1;
  }
  .desktop-nav {
    display: none;
  }
  .menu-toggle {
    display: block;
  }
  .search-bar {
    display: none;
  }
  .donate-hero h1 {
    font-size: 1.75rem;
  }
  .cert-grid {
    grid-template-columns: 1fr;
  }
}

// OpenLearnHub - Global Interactions

(function () {
  // Mobile menu toggle
  const menuToggle = document.getElementById('menu-toggle');
  const mobileNav = document.getElementById('mobile-nav');
  if (menuToggle && mobileNav) {
    menuToggle.addEventListener('click', () => {
      mobileNav.classList.toggle('open');
      const icon = menuToggle.querySelector('i');
      if (icon) {
        if (mobileNav.classList.contains('open')) {
          icon.classList.remove('ri-menu-line');
          icon.classList.add('ri-close-line');
        } else {
          icon.classList.remove('ri-close-line');
          icon.classList.add('ri-menu-line');
        }
      }
    });
  }

  // Donation amount tabs
  const amountTabs = document.querySelectorAll('.amount-tab');
  const donationDesc = document.getElementById('donation-desc');
  const donationSub = document.getElementById('donation-sub');

  if (amountTabs.length && donationDesc) {
    const impactMap = {
      5: 'Your $5 donation will provide 250 hours of learning to people around the world each month.',
      10: 'Your $10 donation will provide 500 hours of learning to people around the world each month.',
      20: 'Your $20 donation will provide 1,000 hours of learning to people around the world each month.',
      40: 'Your $40 donation will provide 2,000 hours of learning to people around the world each month.',
    };

    amountTabs.forEach((tab) => {
      tab.addEventListener('click', () => {
        amountTabs.forEach((t) => t.classList.remove('active'));
        tab.classList.add('active');
        const amount = parseInt(tab.dataset.amount, 10);
        donationDesc.textContent = impactMap[amount] || impactMap[20];
        if (donationSub) {
          donationSub.innerHTML = `Donating $${amount} / month: <a href="#">edit amount</a> · Secure donation`;
        }
      });
    });
  }

  // FAQ accordion
  const accordionHeaders = document.querySelectorAll('.accordion-header');
  accordionHeaders.forEach((header) => {
    header.addEventListener('click', () => {
      const item = header.closest('.accordion-item');
      const isOpen = item.classList.contains('open');
      // Close all
      document.querySelectorAll('.accordion-item').forEach((i) => i.classList.remove('open'));
      // Toggle current
      if (!isOpen) {
        item.classList.add('open');
      }
    });
  });

  // Load more articles
  const loadMoreBtn = document.getElementById('load-more');
  const articleGrid = document.getElementById('article-grid');

  if (loadMoreBtn && articleGrid) {
    const extraArticles = [
      {
        tag: '#JavaScript',
        title: 'Understanding Closures in JavaScript: A Complete Guide',
        author: 'Sarah Chen',
        time: '2 days ago',
        thumb: 'images/ai2.jpg',
        avatar: 'images/avatar3.jpg',
      },
      {
